SELECT v FROM (
 SELECT 'column:'||c.relname||':'||a.attnum||':'||a.attname||':'||format_type(a.atttypid,a.atttypmod)||':'||a.attnotnull||':'||coalesce(pg_get_expr(d.adbin,d.adrelid),'') AS v FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attnum>0 AND NOT a.attisdropped AND c.relnamespace='public'::regnamespace AND c.relname IN ('jobdb_configuration','jobdb_schemas','jobdb_chapter_stories','jobdb_chapter_chapters','jobdb_chapter_artifacts')
 UNION ALL SELECT 'constraint:'||conrelid::regclass::text||':'||conname||':'||pg_get_constraintdef(oid)||':'||convalidated FROM pg_constraint WHERE conrelid IN (SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace AND relname IN ('jobdb_configuration','jobdb_schemas','jobdb_chapter_stories','jobdb_chapter_chapters','jobdb_chapter_artifacts'))
 UNION ALL SELECT 'index:'||i.indexrelid::regclass::text||':'||pg_get_indexdef(i.indexrelid)||':'||i.indisvalid||':'||i.indisready FROM pg_index i JOIN pg_class c ON c.oid=i.indrelid WHERE c.relnamespace='public'::regnamespace AND c.relname IN ('jobdb_configuration','jobdb_schemas','jobdb_chapter_stories','jobdb_chapter_chapters','jobdb_chapter_artifacts')
) objects ORDER BY v COLLATE "C"
